// Mapping Stage Table Definition
const STAGE_MAP = {
  appointmentscheduled: 'LEAD',
  qualifiedtobuy: 'QUALIFIED_LEAD',
  presentationscheduled: 'PITCH_DEMO',
  decisionmakerboughtin: 'PROPOSAL',
  contractsent: 'CLOSING',
  closedwon: 'WON',
  closedlost: 'LOST',
  'Termin vereinbart': 'LEAD',
  'Für Kauf qualifiziert': 'QUALIFIED_LEAD',
  'Präsentation vereinbart': 'PITCH_DEMO',
  'Entscheidungsträger hat zugestimmt': 'PROPOSAL',
  'Vertrag gesendet': 'CLOSING',
  'Abgeschlossen und gewonnen': 'WON',
  'Abgeschlossen und verloren': 'LOST'
};

const rawCompanies = $('Fetch Companies').first()?.json?.results || [];
const rawContacts = $('Fetch Contacts').first()?.json?.results || [];
const rawDeals = $('Fetch Deals').first()?.json?.results || [];

const companies = [];
const companyIds = new Set();
let companiesErrors = 0;

for (const c of rawCompanies) {
  const id = String(c.id || c.properties?.hs_object_id || '');
  const name = String(c.properties?.name || '').trim();
  if (!id || !name) {
    companiesErrors++;
    continue;
  }
  companyIds.add(id);
  companies.push({
    id,
    name,
    domain: c.properties?.domain || undefined,
    industry: c.properties?.industry || 'Allgemein',
    city: c.properties?.city || 'Unbekannt',
    postalCode: c.properties?.zip || undefined,
    employeeCount: Number(c.properties?.numberofemployees) || 1,
    createdAt: c.properties?.createdate || c.createdAt || undefined
  });
}

const contacts = [];
let contactsErrors = 0;
let contactsMatched = 0;

for (const ct of rawContacts) {
  const id = String(ct.id || ct.properties?.hs_object_id || '');
  let companyId = ct.properties?.associatedcompanyid ? String(ct.properties.associatedcompanyid) : '';
  if (!companyId && ct.associations?.companies?.results?.length > 0) {
    companyId = String(ct.associations.companies.results[0].id);
  }
  if (!id || !companyId || !companyIds.has(companyId)) {
    contactsErrors++;
    continue;
  }
  contactsMatched++;
  contacts.push({
    id,
    companyId,
    email: ct.properties?.email || `contact-${id}@leadpilot.internal`,
    firstName: ct.properties?.firstname || '',
    lastName: ct.properties?.lastname || '',
    jobTitle: ct.properties?.jobtitle || undefined,
    name: `${ct.properties?.firstname || ''} ${ct.properties?.lastname || ''}`.trim() || undefined
  });
}

const importedFunnelDeals = [];
let dealsErrors = 0;
const unmappedStages = {};

for (const d of rawDeals) {
  const id = String(d.id || d.properties?.hs_object_id || '');
  const rawStage = String(d.properties?.dealstage || '').trim();
  const mappedStage = STAGE_MAP[rawStage] || STAGE_MAP[rawStage.toLowerCase()] || 'LOST';
  if (!STAGE_MAP[rawStage] && !STAGE_MAP[rawStage.toLowerCase()]) {
    unmappedStages[rawStage] = (unmappedStages[rawStage] || 0) + 1;
  }
  let companyId = '';
  if (d.associations?.companies?.results?.length > 0) {
    companyId = String(d.associations.companies.results[0].id);
  }
  if (!id) {
    dealsErrors++;
    continue;
  }
  importedFunnelDeals.push({
    id,
    companyId: companyId && companyIds.has(companyId) ? companyId : undefined,
    dealName: d.properties?.dealname || `Deal ${id}`,
    stage: mappedStage,
    amount: Number(d.properties?.amount) || 0,
    closeDate: (d.properties?.closedate || '2026-01-01').slice(0, 10),
    pipeline: d.properties?.pipeline || 'default'
  });
}

const audit = {
  companiesLoaded: rawCompanies.length,
  companiesValid: companies.length,
  companiesErrors,
  contactsLoaded: rawContacts.length,
  contactsValid: contacts.length,
  contactsMatched,
  contactsErrors,
  dealsLoaded: rawDeals.length,
  dealsValid: importedFunnelDeals.length,
  dealsErrors,
  unmappedStages
};

const now = new Date();
const dateStr = now.toISOString().slice(0, 10);
const version = `hubspot-${dateStr}`;

const envelope = {
  version,
  generatedAt: now.toISOString(),
  generator: 'n8n',
  generatorSeed: null,
  sourceSystem: 'hubspot',
  hubspotPortalId: 'hubspot-prod',
  periodStart: '2026-01-01',
  counts: {
    companies: companies.length,
    contacts: contacts.length,
    deals: importedFunnelDeals.length,
    activities: 0
  },
  companies,
  contacts,
  importedFunnelDeals,
  activities: [],
  audit
};

return [{ json: envelope }];

const envelope = $input.first().json;

if (!envelope.companies || envelope.companies.length === 0) {
  throw new Error('HubSpot Baseline Assert Error: Keine Companies gefunden.');
}

const companyIds = new Set(envelope.companies.map(c => c.id));
for (const ct of envelope.contacts) {
  if (!companyIds.has(ct.companyId)) {
    throw new Error(`HubSpot Baseline Assert Error: Dangling Contact ${ct.id} -> Company ${ct.companyId}`);
  }
}

return [{ json: envelope }];
